    if(pendingNow){say(pendingText(pendingNow)+(pendingNow.tx?' Press CHECK AGAIN to check the receipt.':'')+' No new BURN can be sent while this wallet request is unresolved.');if(pendingNow.tx)$('burnCheck').hidden=false;$('burnAgree').disabled=false;$('burnGo').disabled=!$('burnAgree').checked;}
