 function restoreDraft(){const r=read('rh-cutaway-draft-v1',70000);if(r?.map)try{const temp=clone(r),vs=E.positions(temp,'v');if(vs.length===1)temp.map=temp.map.map(row=>row.replaceAll('v','.'));const l=E.normalize(temp);if(vs.length===1){const p=vs[0],row=[...l.map[p.y]];row[p.x]='v';l.map[p.y]=row.join('');}return l;}catch{}return C.blank();}
