 const tools=[['wall','WALL'],['floor','FLOOR'],['ladder','LADDER'],['S','ENTRANCE'],['E','EXIT'],['T','TROPHY'],['a','CARD A'],['b','CARD B'],['A','DOOR A'],['B','DOOR B'],['C','CRATE'],['p','PLATE 1'],['P','PLATE 2'],['G','GRID 1'],['H','GRID 2'],['1','SWITCH 1'],['2','SWITCH 2'],['D','POWER DOOR'],['R','EXIT RELAY'],['o','INTEL'],['v','VENT'],['l','LIGHT SWITCH'],['laser','LASER'],['camera','CAMERA'],['drone','DRONE PATH'],['walker','GUARD PATH'],['erase','ERASE DEVICE']];
