 const toolHints={wall:'Click any cell to build solid wall. On a thin row between floors it closes the hatch.',floor:'Click a wall to clear it back to open floor.',ladder:'Click a thin row between two floors to open a ladder hatch.',S:'Moves the entrance to the clicked floor cell.',E:'Moves the exit to the clicked floor cell.',T:'Moves the trophy to the clicked floor cell.',o:'Optional intel dossier to collect.',a:'Keycard A. Opens door A.',b:'Keycard B. Opens door B.',A:'Door A. Needs card A.',B:'Door B. Needs card B.','1':'Floor switch 1. Stepping on it flips circuit 1.','2':'Floor switch 2. Stepping on it flips circuit 2.',D:'Power door. Needs circuit 1.',R:'Exit relay door. Needs circuit 1 and the trophy.',C:'Crate. Pushed, never pulled; can hold a plate down.',p:'Plate 1. Keeps grid 1 open while weighed down.',P:'Plate 2. Keeps grid 2 open while weighed down.',G:'Grid 1. Open while plate 1 is held.',H:'Grid 2. Open while plate 2 is held.',v:'Vent. Two vents connect; the thief uses E.',l:'Light switch the thief can use with L.',laser:'Laser on an empty floor cell away from ladders. Set facing, cycle and offset below.',camera:'Camera on an empty floor cell away from ladders. Set facing below.',drone:'Drone: click both ends of its patrol on one floor, 2 to 12 cells apart. EMP and its circuit blind it.',walker:'Guard: a person walking one floor, seeing 3 cells ahead (1 in the dark). EMP does not stop him; a ladder hatch hides you. Click both ends, 2 to 12 cells apart.',erase:'Click a device or a patrol cell to remove it.'};
 function selectTool(t){if(!editor)return;editor.tool=t;editor.guardStart=null;$('palette').querySelectorAll('[data-tool]').forEach(b=>{const on=b.dataset.tool===t;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});$('editor').dataset.tool=t;updateCoach();}
 function openEditor(){if(!editor)return;editor.active=true;game={level:editor.draft,state:E.create(editor.draft,'ghost'),actions:[],type:'edit',practice:false};show('play');editor.active=true;$('editor').hidden=false;$('replayBar').hidden=true;$('sharedBanner').hidden=editor.kind!=='fortify';$('editorTitle').textContent=editor.kind==='fortify'?'ADD ONE OBSTACLE':'WORKSHOP';const allowed=editor.kind==='fortify'?['wall','laser','camera']:null,name=t=>tools.find(x=>x[0]===t)[1];if(allowed&&!allowed.includes(editor.tool))editor.tool='wall';$('palette').innerHTML=(allowed?[['ONE OF',allowed]]:toolGroups).map(([g,list])=>'<div class="palgroup" role="group" aria-label="'+g+'"><p>'+g+'</p><div>'+list.map(t=>'<button data-tool="'+t+'" title="'+escape(toolHints[t])+'">'+name(t)+'</button>').join('')+'</div></div>').join('');$('palette').querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>selectTool(b.dataset.tool));selectTool(editor.tool);$('editName').value=editor.draft.name;$('editLight').value=editor.draft.lighting?.period?'cycle':editor.draft.lighting?.initialOn===false?'off':'on';$('editNameLabel').hidden=editor.kind==='fortify';$('initialLightLabel').hidden=editor.kind==='fortify';$('newRoom').hidden=editor.kind==='fortify';$('editUndo').hidden=editor.kind==='fortify';$('publishRoom').textContent=editor.kind==='fortify'?'PUBLISH CHANGE':'EXPORT';$('publishRoom').title=editor.kind==='fortify'?'Send your one change and its proof to the server':'Download this room with the route that proves it can be cleared';$('publishRoom').disabled=!editor.proof;$('editX').max=editor.draft.map[0].length-2;$('editY').max=editor.draft.map.length-2;hud();editorFeedback();}
